using System;using System.Linq;using System.IO;using System.Reflection;using Verse;using Verse.AI;using RimWorld;using UnityEngine;using PlayableRecreation;using PlayableRecreation.UI;using Chess;using Chess.Core;using PRQA;
public static class Command{public static string Run(){foreach(var w in Find.WindowStack.Windows.ToList())if(w is Dialog_MiniGame||w is Dialog_Leaderboard)w.Close();Host.Watch=null;TogetherMatch.Reset();var b=(Thing)Host.State["chess"];var map=b.Map;var g=b.TryGetComp<CompMiniGame>().Game;var pair=new Pawn[2];for(int i=0;i<2;i++){var p=PawnGenerator.GeneratePawn(PawnKindDefOf.Colonist,Faction.OfPlayer);p.Name=new NameSingle("QA Rematch "+i);GenSpawn.Spawn(p,b.Position+new IntVec3(i==0?-3:3,0,-3),map);p.needs.food.CurLevelPercentage=1;p.needs.rest.CurLevelPercentage=1;pair[i]=p;}PRMod.Settings.playTogether=true;var log=Host.Root+"/practice-clean.txt";File.WriteAllText(log,"Fresh healthy pair, no forced social interaction, actual New game callback.\n");Action<string> note=s=>File.AppendAllText(log,s+"\n");var f=BindingFlags.NonPublic|BindingFlags.Instance;int stage=0,start=Find.TickManager.TicksGame,last=-1;GameEntry.Commit(g,b,pair[0],pair[1],2,true);Host.Watch=()=>{int t=Find.TickManager.TicksGame;var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(stage==0&&d!=null){var w=(ChessGameWorker)typeof(Dialog_MiniGame).GetField("worker",f).GetValue(d);w.StartNew(2);var core=(ChessGame)typeof(ChessGameWorker).GetField("game",f).GetValue(w);foreach(var mv in new[]{new[]{21,37},new[]{100,68},new[]{22,54},new[]{115,55}}){var legal=core.Legal.Take(core.LegalCount).First(m=>m.From==mv[0]&&m.To==mv[1]);typeof(ChessGameWorker).GetMethod("Commit",f).Invoke(w,new object[]{legal,Time.realtimeSinceStartup});}note("legal checkmate over="+w.IsOver);stage=1;start=t;}else if(stage==1&&t-start>60){typeof(Dialog_MiniGame).GetMethod("StartAnotherMatch",f).Invoke(d,null);note("immediate window="+Find.WindowStack.Windows.Any(x=>x is Dialog_MiniGame)+"\n"+TogetherMatch.Describe());stage=2;start=t;}else if(stage==2){if((t-start)/100!=last){last=(t-start)/100;note((t-start)+" jobs="+pair[0].CurJobDef+","+pair[1].CurJobDef+" window="+(d!=null)+"\n"+TogetherMatch.Describe());}if(d!=null||t-start>2700){note("final sameOpponent="+(d!=null&&typeof(Dialog_MiniGame).GetField("opponentPawn",f).GetValue(d)==pair[1]));Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Clean practice rematch running.";}}
